const std = @import("std");

fn ternarySearch(arr: []const i32, left: usize, right: usize, target: i32) ?usize {
    if (right < left) return null;
    const mid1 = left + (right - left) / 3;
    const mid2 = right - (right - left) / 3;
    if (arr[mid1] == target) return mid1;
    if (arr[mid2] == target) return mid2;
    if (target < arr[mid1]) return ternarySearch(arr, left, mid1 -| 1, target);
    if (target > arr[mid2]) return ternarySearch(arr, mid2 + 1, right, target);
    return ternarySearch(arr, mid1 + 1, mid2 -| 1, target);
}

pub fn main() !void {
    const arr = [_]i32{ 1, 5, 12, 18, 25, 33, 42, 56, 71, 89 };
    const target: i32 = 42;
    if (ternarySearch(&arr, 0, arr.len - 1, target)) |idx| {
        std.debug.print("Found {} at index {}\n", .{target, idx});
    }
}

